public partial class MigrationScene {
 bool livingFixture;bool LivingEnabled=>!((testing||coopCheck)&&!livingFixture);
 readonly Dictionary<int,Node3D> livingRoots=new();Node3D lilyGrave;
 static bool IsTownGuard(string id)=>id.StartsWith("living/guard/");
 SurvivorSettlement Town(int i)=>game.World.Changes.Settlements.FirstOrDefault(s=>s.Index==i);
 bool InLivingLot(double x,double z)=>game.World.LivingLot(x,z);
 void SpawnLivingWorld(){if(!LivingEnabled||dungeon!=null)return;
  foreach(var t in game.World.Changes.Settlements){string id="living/town/"+t.Index;if(!NearActiveSurface(Ground(t.X,t.Z),200)||!uniqueObjects.Add(id))continue;
   var root=new Node3D{Name=ExpeditionGame.SettlementNames[t.Index],Position=Ground(t.X,t.Z)};worldRoot.AddChild(root);livingRoots[t.Index]=root;props.Add(new(){Id=id,Kind=32,Material=t.Index,Position=root.Position,Node=root});
   Box(root,new(0,-.3f,0),new(24,.6f,22),Wood,true);ArtCamp(root);for(int j=0;j<3;j++){var shelter=new Node3D{Position=new((j-1)*6,0,-6)};root.AddChild(shelter);FamilyBed(shelter,Vector3.Zero);Box(shelter,new(0,2.1f,0),new(4,.15f,4),Cloth,true);for(int side=-1;side<=1;side+=2)Box(shelter,new(side*2,1,0),new(.12f,2.2f,4),Wood,true);}
   for(int j=0;j<4;j++){var person=new Node3D{Name="Resident"+j,Position=new((j-1.5f)*2,0,2)};root.AddChild(person);HumanCharacter(person,1,0,true);person.AddChild(new Label3D{Text=new[]{new[]{"Iris / grower","Mal / cook","Jules / guard","Tessa / scout"},new[]{"Gus / mechanic","Nia / medic","Rafi / runner","Len / lookout"},new[]{"Ada / medic","Rook / warden","June / cook","Eli / runner"},new[]{"Voss / commander","Mercer / quartermaster","Rhea / interrogator","Kane / enforcer"}}[t.Index][j],Position=new(0,1.9f,0),FontSize=19,PixelSize=.004f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled});}
   Box(root,new(6,.7f,0),new(2,1.4f,1.2f),Steel,true);Tube(root,new(5.3f,1.5f,0),new(5.3f,2.4f,0),.13f,Steel);root.AddChild(new Label3D{Name="Ledger",Position=new(0,3,0),FontSize=25,PixelSize=.007f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled});
   DressSettlement(root,t);var noah=new Node3D{Name="Noah",Position=new(4,0,-3),Visible=false};root.AddChild(noah);FeverChild(noah,false);
  }
  if(Fever.ArcVersion>0&&Fever.GraveReady&&Fever.GraveX!=0&&NearActiveSurface(Ground(Fever.GraveX,Fever.GraveZ),150)&&uniqueObjects.Add("living/lily-grave")){
   lilyGrave=new Node3D{Name="LilysWoodlandGrave",Position=Ground(Fever.GraveX,Fever.GraveZ)};worldRoot.AddChild(lilyGrave);props.Add(new(){Id="living/lily-grave",Kind=33,Node=lilyGrave,Position=lilyGrave.Position});
   Ellipsoid(lilyGrave,new(0,.13f,0),new(.65f,.18f,1.1f),new(.23f,.18f,.12f));Box(lilyGrave,new(0,.45f,-.9f),new(.13f,.9f,.1f),Wood);Box(lilyGrave,new(0,.65f,-.9f),new(.55f,.1f,.1f),Wood);
   var bear=new Node3D{Position=new(.65f,.08f,-.65f)};lilyGrave.AddChild(bear);LilysTeddy(bear);Box(lilyGrave,new(1,.04f,.5f),new(.55f,.06f,.9f),new(.34f,.19f,.14f));StoryPaper(lilyGrave,new(.85f,.09f,.6f));
   var tent=new Node3D{Position=new(3,0,2)};lilyGrave.AddChild(tent);Box(tent,new(0,.08f,0),new(2,.16f,2),Cloth);Tube(tent,new(0,0,0),new(0,1.2f,0),.03f,Wood);
  }
 }
 void LilysTeddy(Node3D n){Color fur=new(.46f,.31f,.18f);Ellipsoid(n,new(0,.19f,0),new(.12f,.17f,.09f),fur);Ellipsoid(n,new(0,.40f,0),new(.14f,.13f,.1f),fur);foreach(int s in new[]{-1,1}){Ellipsoid(n,new(s*.11f,.49f,0),new(.055f,.055f,.035f),fur);Ellipsoid(n,new(s*.14f,.2f,0),new(.06f,.11f,.055f),fur);Ellipsoid(n,new(s*.08f,.06f,-.03f),new(.07f,.07f,.09f),fur);Box(n,new(s*.05f,.42f,-.095f),new(.018f,.018f,.012f),Ink);}Ellipsoid(n,new(0,.365f,-.09f),new(.06f,.035f,.025f),new(.63f,.48f,.29f));Box(n,new(0,.30f,-.09f),new(.18f,.035f,.025f),new(.29f,.43f,.49f));}
 void TickLivingCommunities(double dt){if(!LivingEnabled||CoopClient||dungeon!=null)return;
  foreach(var p in MillPlayers()){string cell=$"{ExpeditionWorld.Cell(p.Body.Position.X)}:{ExpeditionWorld.Cell(p.Body.Position.Z)}";if(!game.World.Changes.Explored.Contains(cell))game.World.Changes.Explored.Add(cell);}
  game.TickLivingWorld();TickSettlementCampaigns(dt);var town=Town(2);
  if(Fever.ArcVersion>0&&Fever.GraveReady&&!Fever.CitySeen&&!Fever.Offscreen&&Fever.Choice is "truth" or "open" or "reinforce"&&MillPlayers().Any(p=>Distance(p.Body.Position,Ground(town.X,town.Z))<28)){
   Fever.Outcome+="\n\nCITY / "+(Fever.Disclosure=="camp"?$"Noah gives Rook your camp coordinates, {Fever.SharedX:0}, {Fever.SharedZ:0}. Rook sends scavengers for exposed rations.":Fever.Disclosure=="alone"?"Noah tells Rook you travel alone. Rook marks you as an easy person to expel; Ada objects.":"Noah repeats the name you gave him: "+(string.IsNullOrWhiteSpace(Fever.GivenName)?"the traveller":Fever.GivenName)+". Rook puts it on the denied-entry list. Ada refuses to turn you away.");Fever.CitySeen=true;Fever.Timer=game.World.Changes.Time+3600;town.Trust=-10;town.LastEvent="NOAH: That's them. Ask where they came from. / Ada refuses to expel a traveller; Rook closes the stores. The group splits. Restore the clinic within one active day or the evacuation fails.";
   FeverSay("NOAH: You don't get to come here and be one of the good ones. / "+(Fever.Disclosure=="camp"?$"He gives Rook your camp coordinates: {Fever.SharedX:0}, {Fever.SharedZ:0}.":Fever.Disclosure=="alone"?"He tells the guards you travel alone. Rook confiscates your right to barter; Ada refuses to help him enforce it.":"He repeats the name you gave him. It goes on the settlement's denied-entry list."));
   if(Fever.Disclosure=="camp"){var storage=game.Building.Pieces.FirstOrDefault(p=>p.Def.Function=="storage"&&ExpeditionGame.Distance(p.X,p.Z,Fever.SharedX,Fever.SharedZ)<30);if(storage?.Stock?.Length>7)storage.Stock[7]=Math.Max(0,storage.Stock[7]-2);}
   game.WorldDecision("noah/city","Noah identified you at Mercy Row. Ada and Rook split over whether you deserve help. "+Fever.Disclosure+" was used as leverage.");game.Persist();FeverSync();
  }
  if(Fever.CitySeen&&!Fever.Redemption&&!Fever.RedemptionClosed&&game.World.Changes.Time>Fever.Timer){Fever.RedemptionClosed=true;town.Fallen=true;town.LastEvent="The evacuation failed without the medicine and clean supplies the clinic needed. Noah's coat and a final journal remain beneath the cot.";game.Persist();}
  SpawnLivingWorld();
  foreach(var t in game.World.Changes.Settlements)if(!t.Fallen&&(t.DeadResidents&16)==0&&NearActiveSurface(Ground(t.X,t.Z),70))AddEnemy($"living/guard/{t.Index}/{game.Save.Seed}",t.X,t.Z+5,2);
 }
 void DrawLivingCommunities(){if(!LivingEnabled)return;foreach(var t in game.World.Changes.Settlements){if(!livingRoots.TryGetValue(t.Index,out var root)||!GodotObject.IsInstanceValid(root)||!root.IsInsideTree())continue;
  DrawSettlementGrowth(root,t);if(t.Fallen&&root.FindChild("LastGrave",false,false)==null){var grave=new Node3D{Name="LastGrave",Position=new(8,0,-8)};root.AddChild(grave);Box(grave,new(0,.5f,0),new(.12f,1,.1f),Wood);Box(grave,new(0,.7f,0),new(.5f,.1f,.1f),Wood);Box(grave,new(.4f,.04f,0),new(.6f,.08f,.7f),new(.24f,.34f,.44f));StoryPaper(grave,new(.4f,.1f,0));}root.GetNode<Label3D>("Ledger").Text=ExpeditionGame.SettlementNames[t.Index].ToUpperInvariant()+" / "+(t.Fallen?"ABANDONED":$"TRUST {t.Trust} / FOOD {t.Food} / WATER {t.Water}");
  for(int j=0;j<4;j++){var p=root.GetNode<Node3D>("Resident"+j);p.Visible=!t.Fallen&&(t.DeadResidents&(1<<j))==0&&!(j==3&&t.StoryStage==1)&&!SettlementAtWar(t.Index);p.Position=new((j-1.5f)*2+(float)Math.Sin(game.Clock*.22+j)*1.5f,0,2+(float)Math.Cos(game.Clock*.2+j));PoseFigure(p,(float)game.Clock*(j==0?2:5),.25f,false);}
  var boy=root.GetNode<Node3D>("Noah");boy.Visible=t.Index==2&&Fever.CitySeen&&!t.Fallen&&!Fever.Offscreen;root.GetNode<Node3D>("Resident0").Position=t.Index==2&&Fever.CitySeen&&!Fever.Redemption?new(-7,0,-3):root.GetNode<Node3D>("Resident0").Position;
 }}
 WorldProp NearLiving()=>dungeon==null?props.Where(p=>p.Kind is 32 or 33&&Distance(p.Position,player.Position)<(p.Kind==32?8:3)).OrderBy(p=>Distance(p.Position,player.Position)).FirstOrDefault():null;
 string LivingPrompt()=>NearLiving() is WorldProp p?p.Kind==33?"F / EXAMINE THE TEDDY AND WOODLAND GRAVE":"F / "+ExpeditionGame.SettlementNames[p.Material].ToUpperInvariant()+" / COMMUNITY":"";
 bool LivingInteract(){if(!LivingEnabled)return false;var p=NearLiving();if(p==null)return false;if(p.Kind==33){if(!CoopRequest("living","grave"))LivingAction("grave");return true;}if(!CoopRequest("living",p.Material+"|visit"))LivingAction(p.Material+"|visit");return true;}
 void LivingAction(string data){if(CoopClient||!LivingEnabled)return;var p=NearLiving();if(p==null)return;
  if(data=="grave"&&p.Kind==33){Fever.GraveRead=true;game.Change(()=>game.WorldDecision("lily/grave","Lily's grave. Her teddy and Noah's bloodstained coat. He stayed with her until the fever ended; then buried her and left alone."));if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopLivingPanel),-1);else ShowLivingPanel(-1);return;}
  var parts=data.Split('|');if(p.Kind!=32||parts.Length!=2||!int.TryParse(parts[0],out int index)||index!=p.Material)return;
  game.Save.X=player.Position.X;game.Save.Z=player.Position.Z;
  if(parts[1]=="visit"){TickLivingCommunities(0);Town(index).Visits++;BeginSettlementStory(index);if(Town(index).Fallen)game.WorldDecision("town/final-ledger/"+index,Town(index).LastEvent);game.Persist();}
  else if(SettlementCampaignAction(index,parts[1])){}else if(parts[1]=="redeem"){var t=Town(index);if(index!=2||!Fever.CitySeen||Fever.Redemption||Fever.RedemptionClosed||t.Fallen)return;if(game.Craft.Water<8||game.Life.Medicine<3||game.Craft.Materials[4]<12||game.Craft.Materials[5]<6){game.Notice="Clinic restoration needs 8 clean water, 3 medical kits, 12 alloy, 6 electronics";return;}game.Change(()=>{game.Craft.Water-=8;game.Life.Medicine-=3;game.Craft.Materials[4]-=12;game.Craft.Materials[5]-=6;Fever.Redemption=true;t.ClinicFixed=t.WaterFixed=true;t.Water+=8;t.Trust=0;t.LastEvent="The clinic is running. Ada reopens services. Rook has stood down. Noah accepts the help: It doesn't make us alright. He will never join your camp.";game.WorldDecision("noah/redemption","Restored Mercy Row's clinic. Noah accepted help, not an apology. Lily is still gone.");});}
  else if(parts[1]=="medical-barter"){if(Town(index).Trust<0||game.Life.Food<6||game.Craft.Materials[4]<4)return;game.Change(()=>{game.Life.Food-=6;game.Craft.Materials[4]-=4;game.Life.Medicine++;});}
  else if(parts[1]=="service"&&Standing("town/"+index).Value<0){game.Notice="This settlement remembers your actions / personal reputation must recover first";}else if(ResidentAction(index,parts[1])){}else {int before=Town(index).Trust;game.Notice=game.TownAction(index,parts[1]);int delta=Town(index).Trust-before;if(delta!=0){RememberTown(index,delta,Town(index).LastEvent);game.Persist();}}FeverSync();if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopLivingPanel),index);else ShowLivingPanel(index);
 }
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopLivingPanel(int index){if(CoopClient)ShowLivingPanel(index);}
 void ShowLivingPanel(int index){if(index<0){var g=Panel("LILY / THE WOODLAND GRAVE");Text(g,"A shallow grave. Her teddy is beside it, the same blue ribbon around its neck. A bloodstained coat covers Noah's notebook.\n\n'I promised I wouldn't leave her. I kept her warm. She asked for Mum until she couldn't. I buried her before morning. The bear can stay. I need both hands now.'");Button(g,"LEAVE THE BEAR WITH HER",CloseMenu);return;}
  var t=Town(index);var b=Panel(ExpeditionGame.SettlementNames[index].ToUpperInvariant()+" / SURVIVORS");AddSettlementCampaignPanel(b,t);Text(b,$"Trust {t.Trust} / Food {t.Food} / Clean water {t.Water}\n"+t.LastEvent);if(t.Fallen){Text(b,Fever.Offscreen||Fever.RedemptionClosed?"Noah's final note: 'We tried the north road. Lily's bear is still where I left it. If anyone finds this, Ada tried. That's what I want written down.' A familiar blue coat marks a grave outside the clinic.":"The shelters are empty. A stolen ledger records the missing food.");Button(b,"BACK",CloseMenu);return;}
  if(index==2&&Fever.CitySeen)Text(b,Fever.Outcome);Text(b,index==0?"Growers: a shared meal and clean water when their own stores allow it.":index==1?"Mechanics: scrap and dressings, funded by the camp's own rations.":"Medics: illness treatment and gradual recovery support. Noah is with Ada; Rook controls the stores.");
  var actions=new GridContainer{Columns=2};b.AddChild(actions);void Act(string label,string op){Button(actions,label,()=>{if(!CoopRequest("living",index+"|"+op))LivingAction(index+"|"+op);});}
  Act("SHARE 3 FOOD / TRUST +4","food");Act("DELIVER 4 CLEAN WATER / TRUST +5","water");Act("REPAIR THEIR FILTER / 8 ALLOY + 2 ELECTRONICS","repair");Act("REQUEST COMMUNITY SERVICE","service");Act("BARTER MEDICAL KIT / 6 FOOD + 4 ALLOY","medical-barter");Act("STEAL 2 RATIONS / TRUST -18, MAY TURN GUARDS HOSTILE","steal");
  if(index==2&&Fever.CitySeen&&!Fever.Redemption&&!Fever.RedemptionClosed){Text(b,$"ONE WAY TO HELP / restore the clinic before the evacuation in {Math.Max(0,Fever.Timer-game.World.Changes.Time)/60:0} active minutes. Costs: 8 clean water, 3 medical kits, 12 alloy, 6 electronics. This will not earn Noah's forgiveness. Theft or violence closes this route.");Act("RESTORE CLINIC / 8 CLEAN WATER + 3 KITS + 12 ALLOY + 6 ELECTRONICS","redeem");}Text(b,game.Notice);Button(b,"BACK",CloseMenu);
 }
 bool TickTownGuard(Infected e,double dt){if(!IsTownGuard(e.Id))return false;if(SettlementAtWar(int.Parse(e.Id.Split('/')[2])))return TickSettlementFighter(e,dt);if(Town(int.Parse(e.Id.Split('/' )[2])).Fallen){RemoveLivingActor(e);return true;}if(Town(int.Parse(e.Id.Split('/' )[2])).Trust<=-25){TickZombie(e,dt);return true;}e.Cooldown=Math.Max(0,e.Cooldown-dt);if(e.Cooldown>0)return true;var target=(dogPackSource??infected).FirstOrDefault(z=>z!=e&&!IsTownGuard(z.Id)&&!Peaceful(z.Id)&&!PassiveStoryEnemy(z)&&!IsCampaignBoss(z.Id)&&!IsMillBoss(z.Id)&&Distance(z.Body.Position,e.Body.Position)<14);if(target!=null)GuardShot(e,target);return true;}
 void TownGuardDeath(Infected e){if(int.Parse(e.Id.Split('/')[2])==3&&Ledger.State!="enemy")FailLedger("You attacked the Black Ledger. Voss ordered retaliation against your camp.");if(SettlementCombatDeath(e))return;int index=int.Parse(e.Id.Split('/')[2]);var t=Town(index);t.Trust=-100;t.Fallen=true;t.LastEvent="The guard is dead. The residents fled. This community's services are gone.";if(index==2){Fever.Violence=true;Fever.RedemptionClosed=true;}game.Life.Morale=Math.Max(0,game.Life.Morale-20);game.WorldDecision("town/violence/"+index,"Killed a survivor guard. The community evacuated.");game.Skills.Defeated.Add(e.Id);RemoveEnemy(e);game.Persist();}
}
internal partial class ExpeditionMapCanvas {
 void DrawLivingMap(){DrawContentMap();DrawSettlementMissions();if(World.Changes?.Settlements==null)return;foreach(var t in World.Changes.Settlements){var p=Map(t.X,t.Z);DrawCircle(p,5,t.Fallen?Colors.Gray:Colors.LightGreen);DrawString(ThemeDB.FallbackFont,p+new Vector2(7,-7),ExpeditionGame.SettlementNames[t.Index],HorizontalAlignment.Left,-1,11,Colors.LightGreen);}var f=World.Changes.FeverStory;if(f.GraveRead){var p=Map(f.GraveX,f.GraveZ);DrawCircle(p,4,Colors.Burlywood);DrawString(ThemeDB.FallbackFont,p+new Vector2(7,8),"LILY",HorizontalAlignment.Left,-1,10,Colors.Burlywood);}}
}
